// SPDX-License-Identifier: MIT
//
// Cross-checks for Crypto.cs against fixtures generated by Python's
// `cryptography` (for HKDF/ChaCha20-Poly1305) and `srptools` (for SRP-6a).
// Generated with the pyatv venv at:
//   ~/Library/Application Support/MenuBarRemote/venv/bin/python3
// using identical parameters to pyatv (HAP: 3072-bit RFC5054 prime,
// generator 5, SHA-512, identity "Pair-Setup").

using System.Security.Cryptography;
using System.Text;
using AppleTVProtocol;

namespace AppleTVProtocol.Tests;

public class CryptoTests
{
    // ── helpers ──
    private static byte[] H(string hex) => Convert.FromHexString(hex);
    private static string Hex(byte[] bytes) => Convert.ToHexString(bytes).ToLowerInvariant();

    // ───────────────────────── HKDF ─────────────────────────

    [Fact]
    public void HkdfSha512_MatchesRfc5869StyleFixture()
    {
        // Generated via cryptography.hazmat.primitives.kdf.hkdf with SHA-512.
        var ikm  = H("0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b");
        var salt = H("000102030405060708090a0b0c");
        var info = H("f0f1f2f3f4f5f6f7f8f9");
        var expected = H("832390086cda71fb47625bb5ceb168e4c8e26a1a16ed34d9fc7fe92c1481579338da362cb8d9f925d7cb");
        var actual = Crypto.HkdfSha512(ikm, salt, info, outputLength: 42);
        Assert.Equal(Hex(expected), Hex(actual));
    }

    [Fact]
    public void HkdfSha512_StringOverload_MatchesByteOverload()
    {
        // ASCII-encoded labels (HAP's fixed strings) should produce the same OKM.
        var ikm = H("deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef");
        var saltBytes = Encoding.ASCII.GetBytes("Pair-Setup-Encrypt-Salt");
        var infoBytes = Encoding.ASCII.GetBytes("Pair-Setup-Encrypt-Info");
        var fromBytes  = Crypto.HkdfSha512(ikm, saltBytes, infoBytes);
        var fromString = Crypto.HkdfSha512(ikm, "Pair-Setup-Encrypt-Salt", "Pair-Setup-Encrypt-Info");
        Assert.Equal(Hex(fromBytes), Hex(fromString));
    }

    [Fact]
    public void HkdfSha512_HapFixture()
    {
        var ikm = H("deadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeefdeadbeef");
        var expected = H("73d4525ba335520fb1ed3b346527c3f6fcc8cf06234e05b246c25d13e1cdb4f2");
        var actual = Crypto.HkdfSha512(ikm, "Pair-Setup-Encrypt-Salt", "Pair-Setup-Encrypt-Info");
        Assert.Equal(Hex(expected), Hex(actual));
    }

    // ───────── ChaCha20-Poly1305 with 8-byte HAP nonce ─────────

    [Fact]
    public void ChaCha20_RoundTripsWithoutAad()
    {
        var key = H("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
        var nonce8 = Encoding.ASCII.GetBytes("PS-Msg05");
        var plaintext = Encoding.UTF8.GetBytes("hello apple tv pair-setup");
        var cipher = new ChaCha20Poly1305_8ByteNonce(key);

        var ct = cipher.Encrypt(plaintext, nonce8);
        Assert.Equal(plaintext.Length + 16, ct.Length);
        var pt2 = cipher.Decrypt(ct, nonce8);
        Assert.Equal(Hex(plaintext), Hex(pt2));
    }

    [Fact]
    public void ChaCha20_MatchesPythonCryptographyFixture()
    {
        var key       = H("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
        var nonce8    = Encoding.ASCII.GetBytes("PS-Msg05");
        var plaintext = Encoding.UTF8.GetBytes("hello apple tv pair-setup");
        var expectedCipher = H("5c9fee01068c4c56c443b90c063fd08a7ab6a054cb185e99bf75e75eb9dba5c56439161bbf5eb817b9");
        var cipher = new ChaCha20Poly1305_8ByteNonce(key);
        var ct = cipher.Encrypt(plaintext, nonce8);
        Assert.Equal(Hex(expectedCipher), Hex(ct));
    }

    [Fact]
    public void ChaCha20_RoundTripsWithAad()
    {
        var key       = H("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
        var nonce8    = Encoding.ASCII.GetBytes("PS-Msg05");
        var plaintext = Encoding.UTF8.GetBytes("hello apple tv pair-setup");
        var aad       = H("aabbcc");
        var expectedCipher = H("5c9fee01068c4c56c443b90c063fd08a7ab6a054cb185e99bfe10b8858810df3147d55d51536e5d773");
        var cipher = new ChaCha20Poly1305_8ByteNonce(key);
        var ct = cipher.Encrypt(plaintext, nonce8, aad);
        Assert.Equal(Hex(expectedCipher), Hex(ct));
        var pt2 = cipher.Decrypt(ct, nonce8, aad);
        Assert.Equal(Hex(plaintext), Hex(pt2));
    }

    [Fact]
    public void ChaCha20_RejectsWrongKeySize()
    {
        var bad = new byte[16];
        Assert.Throws<ArgumentException>(() => new ChaCha20Poly1305_8ByteNonce(bad));
    }

    [Fact]
    public void ChaCha20_RejectsWrongNonceSize()
    {
        var key    = new byte[32];
        var cipher = new ChaCha20Poly1305_8ByteNonce(key);
        var bad    = new byte[12];
        Assert.Throws<ArgumentException>(() => cipher.Encrypt(new byte[8], bad));
    }

    [Fact]
    public void ChaCha20_TamperedTagFailsDecrypt()
    {
        var key    = H("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f");
        var nonce8 = Encoding.ASCII.GetBytes("PS-Msg05");
        var ct     = new ChaCha20Poly1305_8ByteNonce(key).Encrypt(new byte[8], nonce8);
        ct[^1] ^= 0x01;  // flip the last tag bit
        Assert.Throws<AuthenticationTagMismatchException>(
            () => new ChaCha20Poly1305_8ByteNonce(key).Decrypt(ct, nonce8));
    }

    // ───────────────────────── SRP-6a ─────────────────────────
    // Pinned fixture from srptools (HAP parameters, PIN="1234", fixed salt + ephemerals).
    //
    // SaltHex  = 16-byte server salt
    // APrivHex = 32-byte client ephemeral private (a)
    // BPubHex  = 384-byte server public ephemeral (B) computed from B_priv + verifier
    // APubHex  = 384-byte client public ephemeral (A = g^a mod N)
    // M1Hex    = client proof = H(H(N) XOR H(g) | H(I) | salt | A | B | K)
    // M2Hex    = server proof = H(A | M1 | K)
    // SharedKHex = K = H(S) where S = premaster secret

    private const string PIN      = "1234";
    private const string SaltHex  = "0102030405060708090a0b0c0d0e0f10";
    private const string APrivHex = "1111111111111111111111111111111111111111111111111111111111111111";
    private const string APubHex  =
        "c95341372ca4d0b469f87c0ae37bda635713223b577ef5e8d64a959a54e5395722fea50e71bbd44306055760924a64885805ae13545fcfc7e65f4e7b75c765a1" +
        "12d267f79bffb8353d96ae81cfa64ca7eb687a5dba4cf223b21e1362489ca3e056254b25f610c00643490ea19944f6d3d0872bdcc5fc338bebc8936f30b69592" +
        "4e117f364a4cfc3898eeaa1a4bb98957df8eb046eba3cf42558138ca616a1dc7991426292dd258693bbd4c11816e3064e4a7c536f7255ae61735db25e3cf0349" +
        "eb8b3e9848d0aa572b0f809d8983f1b280581aba96104422fcf088b698f8d899115a5653cc473e87f5e45552a5a126c8b7fc273bd2cd12bfb15ff3501a572b17" +
        "608f16c33f6e971081f3af1be37a0a96748f60d204e935f6a5d2a71303aea434b45bcb9ab6b4444208d3fdf7a00c07a3ba2a09b56b578170c78ba1573ca26924" +
        "06ba8d461e43bb3d160f0024a388d7234236537e29c3604f666c69d7244eae29a0e8b9fa5ee490890e5892973fa535707fbe8f06e90dcbb99c7b39b5eb2b45fb";
    private const string BPubHex  =
        "10f92f711c63995931d536691afaf6f411b37055d8ddc254fc0a5c6d76256fe96433d9092916b836d1a4d4a4fab01385ed8ec7d8828794b9ed89039016efcacc" +
        "6fecf6a07081345c7ba068bb2c69b256eb2eab2fb55acffb50df9bc50c705759057e39d4c5df3d798c44b6cfc800b474a3ed2572487ac27d7a069070abd705ff" +
        "0ce65840c007fb2c6fbd0daf5ae4f7178367ac3f7df85efa7477e1bae5ece64664481a04887d939bedd7270cbbc01187dec5ca5de6112ff629a0d230da80c60a" +
