        "afbcfb8bfd0fecd44fc6c8b496ebbae097f82c6b1956c9d3b501c556a0faa0edf241e493015a656963e94f7f3ad4ef12061ebc44c8c74843c44cf13c214396d6" +
        "d51b89bbc14cf68814c4d445f49a74f9fedd6cb48d16e3c41cf0002f52014ef6c23917809bde86af27631bc43e794b65becad3729f40187a3cc5709eb4bf608c";
    private const string M1Hex = "77238e521072694856f26f12b483b3778bab7d0d709ca57d73ba993d6c2010429f7c0b4cd6de01a5e7868559c23627fb88d168d9f4e9dfcd4b8f6ae262dddd09";
    private const string M2Hex = "953195babd3ebc99d593f4caa9a3c09b0a3a54ae0666d70404845e199b5b57ef8dbba4d2349293cc3d49a984a506c9added6837378185530fd6332ff4e9bf218";
    private const string SharedKHex = "d234b59c428b35f0b78bef76916a6407a7f0afc85f4ef0655b5f982b130c9f4ab7485ddb015ff6e8dd9f7d1b8de8dafbf31c9702b914ca078c13799357f0ff76";

    [Fact]
    public void Srp6a_ProcessChallenge_ProducesExpectedAAndM1()
    {
        var srp = new Srp6aClient();
        srp.Initialize(H(APrivHex));
        srp.SetPin(PIN);

        var (A, M1) = srp.ProcessChallenge(H(SaltHex), H(BPubHex));

        Assert.Equal(APubHex, Hex(A));
        Assert.Equal(M1Hex,   Hex(M1));
        Assert.Equal(SharedKHex, Hex(srp.SharedKey));
    }

    [Fact]
    public void Srp6a_VerifyServerProof_AcceptsCorrectM2()
    {
        var srp = new Srp6aClient();
        srp.Initialize(H(APrivHex));
        srp.SetPin(PIN);
        var (_, M1) = srp.ProcessChallenge(H(SaltHex), H(BPubHex));

        // Should not throw.
        srp.VerifyServerProof(M1, H(M2Hex));
    }

    [Fact]
    public void Srp6a_VerifyServerProof_RejectsTamperedM2()
    {
        var srp = new Srp6aClient();
        srp.Initialize(H(APrivHex));
        srp.SetPin(PIN);
        var (_, M1) = srp.ProcessChallenge(H(SaltHex), H(BPubHex));

        var badM2 = H(M2Hex);
        badM2[0] ^= 0x01;
        Assert.Throws<CryptographicException>(() => srp.VerifyServerProof(M1, badM2));
    }

    [Fact]
    public void Srp6a_RejectsZeroServerPublicKey()
    {
        var srp = new Srp6aClient();
        srp.Initialize(H(APrivHex));
        srp.SetPin(PIN);
        // B = 0 -> B mod N == 0; SRP-6a says abort.
        Assert.Throws<ArgumentException>(
            () => srp.ProcessChallenge(H(SaltHex), new byte[384]));
    }

    [Fact]
    public void Srp6a_ProcessChallenge_RequiresInitializeAndSetPin()
    {
        var srp1 = new Srp6aClient();
        Assert.Throws<InvalidOperationException>(
            () => srp1.ProcessChallenge(H(SaltHex), H(BPubHex)));

        var srp2 = new Srp6aClient();
        srp2.Initialize(H(APrivHex));
        Assert.Throws<InvalidOperationException>(
            () => srp2.ProcessChallenge(H(SaltHex), H(BPubHex)));
    }

    [Fact]
    public void Srp6a_SharedKey_UnavailableBeforeProcessChallenge()
    {
        var srp = new Srp6aClient();
        srp.Initialize(H(APrivHex));
        srp.SetPin(PIN);
        Assert.Throws<InvalidOperationException>(() => { var _ = srp.SharedKey; });
    }
}
